import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"MoParticles","description":"","frontmatter":{},"headers":[],"relativePath":"moparticles/index.md","filePath":"moparticles/index.md","lastUpdated":1788316873000}'),o={name:"moparticles/index.md"};function n(r,e,l,c,d,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="moparticles" tabindex="-1">MoParticles <a class="header-anchor" href="#moparticles" aria-label="Permalink to &quot;MoParticles&quot;">​</a></h1><p>MoParticles is a Paper plugin that brings <strong>Bedrock-style particle effects to Java Edition</strong>. It parses <strong>MoLang</strong> particle definitions — the same JSON format used by Bedrock and the <a href="https://github.com/SkyFabriK/snowstorm" target="_blank" rel="noreferrer">SnowStorm</a> effect ecosystem — and converts them into smooth, Java-compatible animations rendered with vanilla <strong>item displays</strong>.</p><p>No client mod. No custom protocol. No configuration to get started.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>MoParticles turns a static MoLang definition into a playable animation in four steps:</p><ol><li><strong>Parse</strong> — your effect&#39;s <code>.json</code> file (the Bedrock <code>particle_effect</code> format) is read and its MoLang expressions — math functions, query functions, variables — are evaluated by a built-in MoLang engine.</li><li><strong>Bake</strong> — the effect is simulated ahead of time and compressed into a sequence of pre-computed frames. At runtime the plugin only plays back baked data; it never evaluates MoLang per-tick.</li><li><strong>Render</strong> — each frame is played with vanilla <code>ItemDisplay</code> entities and item models, so everything stays within the vanilla protocol.</li><li><strong>Pack</strong> — a resource pack containing the item models and the synthesized particle textures is generated for you at <code>plugins/MoParticles/generated/resourcepack.zip</code>.</li></ol><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;particle .json (MoLang)&quot;] --&gt; B[&quot;MolangEngine&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C[&quot;ParticleSimulator (baked frames)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D[&quot;AnimationPlayer (item displays)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; E[&quot;ResourcePackGenerator&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt; F[&quot;resourcepack.zip&quot;]</span></span></code></pre></div><h2 id="why-moparticles" tabindex="-1">Why MoParticles? <a class="header-anchor" href="#why-moparticles" aria-label="Permalink to &quot;Why MoParticles?&quot;">​</a></h2><ul><li><strong>Reuse existing Bedrock effects.</strong> Drop in any compatible MoLang particle JSON — the bundled examples are taken straight from SnowStorm.</li><li><strong>Pure vanilla rendering.</strong> Item displays + item models. Anything a resource pack can describe, MoParticles can play.</li><li><strong>Cheap at runtime.</strong> All of the expensive simulation happens once, when the effect is loaded — not on every tick.</li><li><strong>A real API.</strong> Your plugin can list, play, and stop effects with a few lines of code.</li></ul><h2 id="included-effects" tabindex="-1">Included effects <a class="header-anchor" href="#included-effects" aria-label="Permalink to &quot;Included effects&quot;">​</a></h2><p>Three effects ship with the plugin, extracted from <a href="https://github.com/SkyFabriK/snowstorm" target="_blank" rel="noreferrer">SnowStorm</a>:</p><table tabindex="0"><thead><tr><th>Effect ID</th><th>Description</th></tr></thead><tbody><tr><td><code>snowstorm:fire</code></td><td>A custom fire particle with tinted, fading embers</td></tr><tr><td><code>snowstorm:loading</code></td><td>SnowStorm&#39;s loading-circle spinner</td></tr><tr><td><code>snowstorm:rainbow</code></td><td>A looping rainbow particle animation</td></tr></tbody></table><p>Try one out right away:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/moparticles playhere snowstorm:fire</span></span></code></pre></div><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://github.com/Chest-Solutions/MoParticles" target="_blank" rel="noreferrer">GitHub repository</a></li><li><a href="https://github.com/Chest-Solutions/MoParticles/releases" target="_blank" rel="noreferrer">Releases &amp; downloads</a></li><li><a href="/moparticles/getting-started">Next: Getting started →</a></li></ul>`,16)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
